PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tenant_learn_availability (
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  school_level TEXT NOT NULL CHECK(school_level IN ('P5','P6')),
  domain TEXT NOT NULL CHECK(domain IN ('listen','speak','read','write')),
  lesson_limit INTEGER NOT NULL DEFAULT 0 CHECK(lesson_limit BETWEEN 0 AND 200),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(tenant_id,school_level,domain)
);
CREATE INDEX IF NOT EXISTS idx_tenant_learn_availability ON tenant_learn_availability(tenant_id,school_level,domain);
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P5','listen',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P5' AND content_type IN ('audio','video_ref') AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P5','speak',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P5' AND content_type='oral_prompt' AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P5','read',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P5' AND content_type IN ('article','lesson') AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P5','write',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P5' AND content_type='writing_prompt' AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P6','listen',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P6' AND content_type IN ('audio','video_ref') AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P6','speak',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P6' AND content_type='oral_prompt' AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P6','read',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P6' AND content_type IN ('article','lesson') AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO tenant_learn_availability(tenant_id,school_level,domain,lesson_limit)
SELECT t.id,'P6','write',COUNT(c.id) FROM tenants t LEFT JOIN content_items c ON c.status='published' AND c.school_level='P6' AND content_type='writing_prompt' AND (c.scope='global' OR (c.scope='tenant' AND c.tenant_id=t.id)) GROUP BY t.id;
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-write-p5-lost-wallet','writing_prompt','P5 Continuous Writing · The Lost Wallet','P5','Honesty','https://www.moe.gov.sg/-/media/files/primary/2020-english-language-primary.ashx','owned','published',1,'Original Singapore primary writing practice aligned to purpose, audience, context, idea development and revision.','English Mastery original · aligned to MOE English Language Syllabus 2020 and PSLE 2026 format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p5-lost-wallet-v1','r8-write-p5-lost-wallet',1,'{"writingType":"continuous","prompt":"Write a story about finding something valuable that does not belong to you. Show what you noticed, the choice you had to make, what you did, and how the experience changed the way you thought about honesty.","minimumWords":120,"planningPrompts":["What valuable item is found, and where?","What temptation or difficulty makes the choice meaningful?","What action shows honesty?","How does the ending show a lesson learned?"]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
