INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p6-misunderstanding-v1','r8-write-p6-misunderstanding',1,'{"writingType":"continuous","prompt":"Write a story about a misunderstanding that damages a friendship or working relationship. Show how the misunderstanding begins, why it becomes worse, and what finally leads to the truth.","minimumWords":150,"planningPrompts":["What evidence is misunderstood?","Why do the characters fail to clarify it early?","What turning point reveals the truth?","How does the relationship change afterwards?"],"picturePrompts":["A message on a phone is read without its full context.","Two friends stand apart after an argument.","A misplaced object is found in an unexpected place."]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
