INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p6-small-act-v1','r8-write-p6-small-act',1,'{"writingType":"continuous","prompt":"Write a story in which a small act has a much greater effect than expected. Make the cause-and-effect chain clear and end by showing why the act mattered.","minimumWords":150,"planningPrompts":["What small action begins the chain?","Who notices or benefits from it?","How does the effect grow?","What final moment gives the story meaning?"],"picturePrompts":["A student shares an umbrella in sudden rain.","Someone returns a dropped card holder to its owner.","A handwritten note of encouragement is left on a desk."]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
