INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p6-risky-choice-v1','r8-write-p6-risky-choice',1,'{"writingType":"continuous","prompt":"Write a story about making a risky choice when there was little time to decide. Show what information was available, what could go wrong, and how you handled the consequences.","minimumWords":150,"planningPrompts":["Why must the decision be made quickly?","What are the risks and possible benefits?","How do thoughts and actions show the pressure?","What consequence makes the ending convincing?"],"picturePrompts":["A warning sign blocks the usual route.","A phone shows very little time remaining before an appointment.","Two possible paths lead in different directions."]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
