INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p6-initiative-v1','r8-write-p6-initiative',1,'{"writingType":"continuous","prompt":"Write a story about noticing a problem before anyone asked you to help. Show how you took initiative, the obstacles you faced, and how others responded.","minimumWords":150,"planningPrompts":["What problem do others overlook?","Why do you decide to act?","What obstacle tests your initiative?","How does the response of others complete the story?"],"picturePrompts":["Water has spilled across a busy walkway.","An event booth has a growing queue and no organiser nearby.","A group of students begins reorganising materials without being asked."]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
