INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p6-reading-campaign-v1','r8-write-p6-reading-campaign',1,'{"writingType":"situational","prompt":"Your school librarian has invited suggestions for a student reading campaign. Write an email proposing one activity. Explain the activity, who it is for, how it will work, two resources needed, and why students are likely to take part. Use a clear and persuasive tone.","minimumWords":100,"planningPrompts":["What is your purpose and audience?","What details make the proposal practical?","Which benefits will persuade the librarian?","How will you organise the email into clear paragraphs?"]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
