INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-write-p6-event-feedback-v1','r8-write-p6-event-feedback',1,'{"writingType":"situational","prompt":"You attended a youth event at a community centre. The organiser has asked for feedback. Write an email describing one part that worked well, one difficulty you noticed, a specific improvement, and one reason you would or would not recommend the event to other students.","minimumWords":100,"planningPrompts":["What is the purpose of the feedback?","How can criticism remain constructive?","What specific improvement follows from the difficulty?","How will you justify your recommendation?"]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
