INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p5-morning-market','oral_prompt','A Morning at the Market','P5','Community','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-morning-market-v1','r8-speak-p5-morning-market',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud clearly. Use suitable pace, phrasing and expression.","referenceText":"On Saturday morning, the neighbourhood market was already full of activity. Stallholders arranged baskets of fruit, while customers compared prices and greeted familiar faces. Near the entrance, a volunteer showed an elderly visitor where to find the lift. At another stall, a child carefully counted coins before buying breakfast for the family. The market was busy, but people still made space for one another. By the time we left, I realised that a market is more than a place to shop. It is also a place where neighbours meet, help one another and feel part of a community."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p5-morning-market','S-PRON',1);
