INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p5-school-garden','oral_prompt','The School Garden','P5','Environment','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-school-garden-v1','r8-speak-p5-school-garden',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud as if you are introducing the garden to visitors.","referenceText":"Our school garden began with only a few pots beside the canteen. Today, it has herbs, flowering plants and a small vegetable patch cared for by different classes. Students take turns to water the plants and remove fallen leaves. We have also learned to check the soil before watering so that we do not waste water. During recess, some pupils visit the garden simply to enjoy the quieter space. The garden has taught us that caring for living things requires patience. Small actions, repeated regularly, can gradually transform an empty corner into a place everyone values."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p5-school-garden','S-PRON',1);
