INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p5-cycling-safely','oral_prompt','Cycling Safely','P5','Safety','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-cycling-safely-v1','r8-speak-p5-cycling-safely',1,'{"mode":"reading_aloud","prompt":"Read the safety announcement aloud so younger pupils can understand it easily.","referenceText":"Cycling can be a convenient way to travel, but every rider has a responsibility to keep others safe. Before setting off, check that your brakes work and that your helmet fits properly. Slow down near pedestrians and give a clear signal before changing direction. If a path is crowded, be prepared to get off and push your bicycle. At night or in poor weather, make sure that you can be seen. Safe cycling is not about reaching your destination as quickly as possible. It is about making careful choices so that everyone can share the path confidently."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p5-cycling-safely','S-PRON',1);
