INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p5-reading-corner','oral_prompt','A New Reading Corner','P5','School','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-reading-corner-v1','r8-speak-p5-reading-corner',1,'{"mode":"reading_aloud","prompt":"Read the announcement aloud with an inviting and enthusiastic tone.","referenceText":"Next month, our class will create a new reading corner. Instead of filling it only with storybooks, we will include magazines, comics, information books and student recommendations. Everyone may suggest one title that they think classmates will enjoy. We will also make short recommendation cards explaining what each book is about and who might like it. The aim is not to see who can read the most books. We want to help one another discover different kinds of reading. If everyone contributes one thoughtful suggestion, our small corner can become a place full of new ideas."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p5-reading-corner','S-PRON',1);
