INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p5-rainy-day','oral_prompt','The Rainy-Day Plan','P5','Problem Solving','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-rainy-day-v1','r8-speak-p5-rainy-day',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud, showing the change from disappointment to optimism.","referenceText":"Dark clouds appeared just as our class reached the park for an outdoor activity. Within minutes, heavy rain forced everyone under a shelter. At first, we were disappointed because weeks of planning seemed wasted. Then our teacher asked each group to think of an activity that could be done safely under cover. One group created a nature quiz, another organised a drawing challenge, and my group interviewed classmates about the sounds and smells of the rain. The day did not go according to plan, but it was still enjoyable. We learned that a good experience sometimes depends on how quickly we adapt."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p5-rainy-day','S-PRON',1);
