INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p5-rainy-day','S-PURPOSE',1);
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p6-community-library','oral_prompt','The Community Library Project','P6','Community','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p6-community-library-v1','r8-speak-p6-community-library',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud as if you are speaking to an audience at a school assembly.","referenceText":"A group of residents noticed that many useful books were being thrown away during household clean-ups. Instead of letting the books go to waste, they placed a weatherproof cabinet near the community hall and invited neighbours to share books there. The idea was simple: anyone could take a book, return it later or replace it with another title. At first, only a few people used the cabinet. Soon, children began exchanging adventure stories, adults donated novels, and volunteers organised the shelves each weekend. The project succeeded because people trusted one another to use a shared resource responsibly. It showed how a small idea can strengthen a community when everyone contributes."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-community-library','S-PRON',1);
