INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-community-library','S-PURPOSE',1);
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p6-water-refill','oral_prompt','Choosing to Refill','P6','Environment','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p6-water-refill-v1','r8-speak-p6-water-refill',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud with clear emphasis on the writer''s main message.","referenceText":"For a school event, organisers once ordered hundreds of small bottles of water because they seemed convenient. By the end of the day, bins were overflowing with empty bottles, many of them only partly used. The following year, the organisers tried a different approach. Students were asked to bring reusable bottles, and refill stations were placed around the school. Clear signs showed where the stations were, while student volunteers reminded participants to refill rather than buy another drink. The change required more planning, but it greatly reduced waste. Convenience is useful, yet thoughtful planning can often give us a solution that is both practical and responsible."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-water-refill','S-PRON',1);
