INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-water-refill','S-PURPOSE',1);
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p6-first-aid','oral_prompt','Learning First Aid','P6','Safety','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p6-first-aid-v1','r8-speak-p6-first-aid',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud in a calm, informative tone.","referenceText":"When an accident happens, people often want to help immediately. However, useful help begins with staying calm and checking what is safe to do. During a basic first-aid workshop, our instructor taught us to look for danger, call an adult or emergency service when necessary, and avoid actions that could make an injury worse. We practised explaining an emergency clearly and learned why accurate information matters. The workshop did not turn us into medical experts, nor was that its purpose. Instead, it taught us how to respond responsibly while waiting for trained help. Knowing what not to do can be just as important as knowing what to do."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-first-aid','S-PRON',1);
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-first-aid','S-FLUENCY',1);
