INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-first-aid','S-PURPOSE',1);
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p6-team-rehearsal','oral_prompt','The Final Rehearsal','P6','Teamwork','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p6-team-rehearsal-v1','r8-speak-p6-team-rehearsal',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud, using expression to show tension and relief.","referenceText":"The final rehearsal began badly. One speaker forgot an important line, a prop broke, and the music started at the wrong moment. For a few seconds, everyone talked at once. Our group leader stopped the rehearsal and asked us to solve one problem at a time. We replaced the broken prop with a simpler one, marked the music cue more clearly and gave the speaker a short prompt card. The second rehearsal was not perfect, but it ran smoothly. More importantly, we stopped blaming one another and began listening. A strong team is not one that never faces problems. It is one that can stay focused and solve them together."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-team-rehearsal','S-PRON',1);
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-team-rehearsal','S-FLUENCY',1);
