INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-team-rehearsal','S-PURPOSE',1);
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p6-digital-break','oral_prompt','A Short Digital Break','P6','Well-being','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p6-digital-break-v1','r8-speak-p6-digital-break',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud with a reflective, balanced tone.","referenceText":"Screens are useful for learning, communication and entertainment, but it is easy to keep using them longer than intended. One family decided to try a short screen-free period after dinner. At first, everyone reached for a device out of habit. Gradually, they found other ways to use the time. They played a quick card game, prepared things for the next day and talked about what had happened at work and school. Nobody decided that screens were bad or unnecessary. The experiment simply made the family more aware of how they used their attention. Sometimes, a small pause helps us choose our habits instead of following them automatically."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-digital-break','S-PRON',1);
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-digital-break','S-FLUENCY',1);
