INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-digital-break','S-PURPOSE',1);
INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p6-heritage-trail','oral_prompt','A Neighbourhood Heritage Trail','P6','Heritage','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original Reading Aloud passage for pronunciation, fluency and expression.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p6-heritage-trail-v1','r8-speak-p6-heritage-trail',1,'{"mode":"reading_aloud","prompt":"Read the passage aloud as if you are introducing a local trail to visitors.","referenceText":"Many people walk through their neighbourhood every day without noticing the stories around them. A student group decided to create a short heritage trail using old photographs, interviews with long-time residents and information from public displays. They marked places where a cinema, market and playground had once stood, then explained how each site had changed. The students were surprised to learn that ordinary places could carry important memories. Their final trail did not try to preserve the neighbourhood exactly as it had been. Instead, it helped younger residents understand how the area had developed and why listening to different generations can give us a richer picture of the place we call home."}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
INSERT OR IGNORE INTO content_skills(content_id,skill_id,coverage) VALUES('r8-speak-p6-heritage-trail','S-PRON',1);
