INSERT OR IGNORE INTO content_items(id,content_type,title,school_level,topic,source_url,licence,status,active_version,description,source_attribution,published_at,scope) VALUES('r8-speak-p5-canteen-queue','oral_prompt','A Busy Canteen Queue','P5','Courtesy','https://www.seab.gov.sg/psle/psle-formats-examined-in-2026/','owned','published',1,'Original stimulus-based oral conversation practice using an everyday-life scene.','English Mastery original · aligned to MOE syllabus and PSLE oral communication format',CURRENT_TIMESTAMP,'global');
INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-canteen-queue-v1','r8-speak-p5-canteen-queue',1,'{"mode":"stimulus","prompt":"Look at the scene and speak about what stands out. Then explain how students can make a busy canteen safer and more pleasant for everyone.","stimulusAlt":"A school canteen during recess: one orderly queue, two pupils trying to join near the front, a student carrying a tray carefully, and another pupil helping to pick up a dropped spoon.","followUpGoals":["describe relevant details","connect to personal experience","give an opinion with a reason"]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
