INSERT OR IGNORE INTO content_versions(id,content_id,version,body_json,generation_model,curriculum_version_id,review_status) VALUES('r8-speak-p5-playground-share-v1','r8-speak-p5-playground-share',1,'{"mode":"stimulus","prompt":"Describe what you notice and explain how people with different activities can share the same public space responsibly.","stimulusAlt":"A neighbourhood playground and exercise area: young children on play equipment, older pupils playing ball nearby, an adult exercising, and a sign asking users to keep pathways clear.","followUpGoals":["describe relevant details","connect to personal experience","give an opinion with a reason"]}','r8-syllabus-original','SG-PRIMARY-ENGLISH-2020-PSLE-2026','approved');
